/**
 * Inicializa el objeto TFT_ST7735.
 * @param CS_pin Número del pin asociado al Chip Select.
 * @param DC_pin Número del pin asociado al selector Dato/Comando.
 * @param MOSI_pin Número del pin asociado al MOSI.
 * @param SCLK_pin Número del pin asociado al Clock.
 * @param RST_pin Número del pin asociado al Reset.
 */
TFT_ST7735::TFT_ST7735(int CS_pin, int DC_pin, int MOSI_pin, int SCLK_pin, int RST_pin){
    _CS_pin = CS_pin;
    _DC_pin = DC_pin;
    _MOSI_pin = MOSI_pin;
    _SCLK_pin = SCLK_pin;
    _RST_pin = RST_pin;
    
}

/**
 * Inicializa la pantalla y la pinta completamente negra.
 */
void TFT_ST7735::begin(){
    _tft = Adafruit_ST7735(_CS_pin, _DC_pin, _MOSI_pin, _SCLK_pin, _RST_pin);
    _tft.initR(INITR_BLACKTAB);  // Initialize the display
    _tft.fillScreen(ST77XX_BLACK); // Clear the screen
}

/**
 * Escribe texto en la pantalla.
 * @param color Color del texto.
 * @param text Un string con el texto a imprimir.
 * @param size Tamaño de fuente.
 * @param posX La posición X del inicio del texto.
 * @param posY La posición Y del inicio del texto.
 */
void TFT_ST7735::write(int16_t color, String text, int size, int pos_X, int pos_Y){
    _tft.setTextColor(color); // Set text color
    _tft.setTextSize(size); // Set text size
    _tft.setCursor(pos_X, pos_Y); // Set text position
    _tft.println(text);
}

/**
 * Dibuja el logo de Cóndor de 100x100 en la posición indicada.
 * @param posX La posición X del inicio del logo.
 * @param posY La posición Y del inicio del logo.
 */
void TFT_ST7735::condor_logo(int posX, int posY){
    _tft.drawBitmap(posX, posY, logo, 100, 100, ST7735_WHITE);
}
